<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_role('Administrator','Management','Event','HR','Author','IT');$pageTitle='Management Dashboard';$pdo=db();$counts=[];foreach(['pending users'=>"SELECT COUNT(*) FROM users WHERE account_status='pending'",'pending bookings'=>"SELECT COUNT(*) FROM bookings WHERE status='pending_review'",'confirmed bookings'=>"SELECT COUNT(*) FROM bookings WHERE status='confirmed'",'upcoming events'=>"SELECT COUNT(*) FROM events WHERE status='confirmed' AND start_at>=NOW()"] as $k=>$q)$counts[$k]=(int)$pdo->query($q)->fetchColumn();$recent=$pdo->query("SELECT * FROM vw_booking_summary ORDER BY created_at DESC LIMIT 8")->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Operations</div><h1 class="admin-title">Management dashboard</h1><p class="kicker">Operational overview for bookings, events and account approvals.</p></div><a class="btn btn-gold" href="<?=url('user/bookings/create.php')?>">Open booking form</a></div><div class="stats"><?php foreach($counts as $k=>$v):?><div class="stat"><small><?=e(ucwords($k))?></small><strong><?=$v?></strong></div><?php endforeach;?></div><div class="panel" style="margin-top:25px"><div class="section-head"><div><div class="eyebrow">Latest requests</div><h2 style="font-size:34px">Booking queue.</h2></div><a class="btn btn-outline btn-sm" style="color:var(--forest);border-color:#bbb" href="<?=url('admin/bookings/index.php')?>">View all</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Ref</th><th>Owner</th><th>Event</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($recent as $b):?><tr><td><?=e($b['booking_ref'])?></td><td><?=e($b['user_name'])?></td><td><?=e($b['event_title'])?></td><td><?=date('d M Y',strtotime($b['start_at']))?></td><td><span class="badge <?=$b['status']==='confirmed'?'badge-green':($b['status']==='rejected'?'badge-red':'badge-gold')?>"><?=e(ucwords(str_replace('_',' ',$b['status'])))?></span></td><td><a class="btn btn-outline btn-sm" style="color:var(--forest);border-color:#bbb" href="<?=url('admin/bookings/view.php?id='.$b['id'])?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
